mapper.select:

SELECT scores.*,DENSE_RANK() OVER (ORDER BY score DESC) AS ranking FROM (
    SELECT 
    FROM sys_user u LEFT JOIN alert_record a ON a.driver_id=u.id AND 
    WHERE u.role='DRIVER' AND u.fleet_id=#{fleetId}
    GROUP BY 
) scores ORDER BY score DESC,driver_id ASC LIMIT #{limit} OFFSET #{offset}
